async function borrarCliente(id){
 const c=cli(id),vs=vehOfCli(id),ss=servOfCli(id);
 if(!await confirmBox(`¿Eliminar a <b>${esc(c.nombre)}</b>? Se borrarán también sus ${vs.length} vehículo(s) y ${ss.length} servicio(s) de la app.<br><span class="muted">Los PDF ya guardados en la carpeta de la PC no se borran.</span>`,'Eliminar'))return;
 const vids=new Set(vs.map(v=>v.id));
 S.servicios=S.servicios.filter(s=>s.clienteId!==id&&!vids.has(s.vehiculoId));
 S.vehiculos=S.vehiculos.filter(v=>v.clienteId!==id);S.clientes=S.clientes.filter(x=>x.id!==id);
 save();toast('Cliente eliminado','ok');go('clientes');
}
