/* ---------- Vehículos ---------- */
let qVeh='';
function vVehiculos(){
 return `<div class="top"><h1>Vehículos<small>${S.vehiculos.length} registrados</small></h1>
 <input class="search" id="qVeh" placeholder="Buscar matrícula, marca, modelo o cliente…" value="${esc(qVeh)}" oninput="App.filtVeh(this.value)">
 <button class="btn pri" onclick="App.formVehiculo()">+ Nuevo vehículo</button></div>
 <div class="card"><div class="tw"><table><thead><tr><th>Matrícula</th><th>Vehículo</th><th>Cliente</th><th class="r">Último km</th><th class="r">Próx. service</th><th>Última visita</th><th class="r">Total gastado</th></tr></thead><tbody id="tVeh">${rowsVeh()}</tbody></table></div></div>`;
}
function rowsVeh(){
 const q=qVeh.toLowerCase().trim(),qm=normMat(qVeh);
 const list=S.vehiculos.filter(v=>{if(!q)return true;const c=cli(v.clienteId);return (qm&&normMat(v.matricula).includes(qm))||[v.marca,v.modelo,c?.nombre].some(x=>String(x||'').toLowerCase().includes(q));}).sort((a,b)=>a.matricula.localeCompare(b.matricula));
 if(!list.length)return `<tr><td colspan="7" class="empty">${S.vehiculos.length?'Sin resultados.':'Todavía no hay vehículos.'}</td></tr>`;
 return list.map(v=>{const c=cli(v.clienteId),ls=lastSvc(v),st=stats(servOfVeh(v.id));return `<tr class="click" onclick="App.go('vehiculo','${v.id}')"><td><span class="mat">${esc(v.matricula)}</span></td><td>${esc([v.marca,v.modelo,v.anio].filter(Boolean).join(' '))}</td><td>${esc(c?.nombre)}</td><td class="r">${fnum(lastKm(v))}</td><td class="r">${lastProx(v)?fnum(lastProx(v)):'—'}</td><td>${fdate(ls?.fecha)||'—'}</td><td class="r">${money(st.total)}</td></tr>`;}).join('');
}
function formVehiculo(id,clienteId,cb){
 const v=id?veh(id):{clienteId:clienteId||''};
 if(!S.clientes.length){toast('Primero creá un cliente','err');return formCliente(null,c=>formVehiculo(null,c.id,cb));}
 modal(id?'Editar vehículo':'Nuevo vehículo',`<div class="form">
  <label class="f full">Cliente (dueño) *<select id="v_cli"><option value="">— Elegir —</option>${[...S.clientes].sort(byName).map(c=>`<option value="${c.id}" ${c.id===v.clienteId?'selected':''}>${esc(c.nombre)}</option>`).join('')}</select></label>
  <label class="f">Matrícula *<input id="v_mat" value="${esc(v.matricula)}" style="text-transform:uppercase" placeholder="SBA 1234"></label>
  <label class="f">Marca<input id="v_marca" value="${esc(v.marca)}" placeholder="Volkswagen"></label>
  <label class="f">Modelo<input id="v_modelo" value="${esc(v.modelo)}" placeholder="Gol Trend"></label>
  <label class="f">Año<input id="v_anio" value="${esc(v.anio)}" inputmode="numeric"></label>
  <label class="f">Color<input id="v_color" value="${esc(v.color)}"></label>
  <label class="f">Combustible<select id="v_comb">${['','Nafta','Diésel','Híbrido','Eléctrico','GNC'].map(x=>`<option ${x===(v.combustible||'')?'selected':''}>${x}</option>`).join('')}</select></label>
  <label class="f">N° de chasis / motor<input id="v_chasis" value="${esc(v.chasis)}"></label>
  <label class="f">Km al ingresar<input id="v_km" value="${esc(v.kmInicial)}" inputmode="numeric"></label>
  <label class="f full">Notas<textarea id="v_notas">${esc(v.notas)}</textarea></label>
 </div>`,
 [{label:'Cancelar'},{label:'Guardar',cls:'pri',onClick:async()=>{
  const cid=val('v_cli'),mat=val('v_mat').toUpperCase().replace(/\s+/g,' ');
  if(!cid){toast('Elegí el cliente','err');return false;}
  if(!normMat(mat)){toast('La matrícula es obligatoria','err');return false;}
  if(S.vehiculos.some(x=>x.id!==id&&normMat(x.matricula)===normMat(mat))){toast('Ya existe un vehículo con esa matrícula','err');return false;}
  const o=id?v:{id:uid(),creado:today()};
  Object.assign(o,{clienteId:cid,matricula:mat,marca:val('v_marca'),modelo:val('v_modelo'),anio:val('v_anio'),color:val('v_color'),combustible:val('v_comb'),chasis:val('v_chasis'),kmInicial:n(val('v_km'))||0,notas:val('v_notas')});
  if(!id)S.vehiculos.push(o);
  save();await ensureClientFolders(cli(cid));
  toast(id?'Vehículo actualizado':'Vehículo creado','ok');
  if(cb)cb(o);else render();
 }}]);
}
async function borrarVehiculo(id){
 const v=veh(id),ss=servOfVeh(id);
 if(!await confirmBox(`¿Eliminar el vehículo <b>${esc(v.matricula)}</b> y sus ${ss.length} servicio(s)?<br><span class="muted">Los PDF ya guardados en la PC no se borran.</span>`,'Eliminar'))return;
 S.servicios=S.servicios.filter(s=>s.vehiculoId!==id);S.vehiculos=S.vehiculos.filter(x=>x.id!==id);
 save();toast('Vehículo eliminado','ok');go('cliente',v.clienteId);
}
